const $ = s => document.querySelector(s);
const icon = (name, cls='') => `<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc = str => String(str).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(value)+' ₽';
const scenarios = {
  job:{name:'Подозрительная просьба',short:'Подозрительная просьба',sub:'Платёж ради обещанной выплаты',context:'Клиенту обещают выплатить деньги за выполненную работу. Для получения выплаты собеседник просит сначала перевести 12 000 ₽.',symbol:'file',amount:12000,recipient:'Алексей К.',sender:'Анна · менеджер',balance:186350,
    messages:['Вы заработали 36 000 ₽. Сумма готова к выводу.','Для активации выплаты внесите обеспечительный платёж 12 000 ₽.','Если банк спросит, скажите, что возвращаете долг. Оплатить нужно за 10 минут.'],
    result:'Есть признаки<br>обмана',intro:'Вас просят заплатить за получение заработка и скрыть цель перевода.',findings:[['Платёж за получение заработка','«Для активации выплаты внесите обеспечительный платёж»','Требование сначала заплатить, чтобы получить заработанное, — признак мошеннической схемы.'],['Просьба скрыть цель перевода','«Скажите, что возвращаете долг»','Собеседник подсказывает, как обойти банковскую проверку.'],['Давление по времени','«Оплатить нужно за 10 минут»','Вас торопят и не оставляют времени на проверку.']]},
  purchase:{name:'Оплата покупки',short:'Оплата покупки',sub:'Расчёт после осмотра товара',context:'Клиент договорился купить товар у частного продавца за 48 000 ₽. В переписке обсуждается оплата после личного осмотра.',symbol:'wallet',amount:48000,recipient:'Алексей К.',sender:'Алексей · продавец',balance:186350,
    messages:['Можно приехать посмотреть товар в субботу?','Конечно, сначала осмотрите товар, потом оплатите.','48 000 ₽. Перевод на моё имя — Алексей К.'],
    result:'Пока не вижу<br>явных признаков обмана',intro:'Это не подтверждает личность продавца и наличие товара. Проверьте их перед оплатой.',findings:[['Оплата после осмотра','«Сначала осмотрите товар, потом оплатите»','Собеседник предлагает личную встречу. Убедитесь, что товар действительно у продавца.'],['Имя совпадает с получателем','«Перевод на моё имя — Алексей К.»','В переводе указано такое же имя. Совпадение имени само по себе не гарантирует честность сделки.']]},
  unclear:{name:'Неполная переписка',short:'Неполная переписка',sub:'Сумма есть, цель неясна',context:'Клиент получил реквизиты и просьбу перевести 25 000 ₽. В выбранных сообщениях не видно, кому и за что он платит.',symbol:'chat',amount:25000,recipient:'Ирина М.',sender:'Получатель',balance:186350,
    messages:['Отправьте сюда 25 000 ₽.','Реквизиты ниже.'],result:'Недостаточно<br>информации',intro:'В сообщениях не видно, за что вы платите и кто попросил перевод.',findings:[['Не видна цель платежа','«Отправьте сюда 25 000 ₽»','Добавьте начало разговора и сообщения, в которых обсуждается оплата.']]}
};
scenarios.normal={name:'Обычный перевод',short:'Обычный перевод',sub:'Без сигнала антифрода',context:'Клиент возвращает знакомому 2 500 ₽. Получатель знаком банку, операция не вызвала подозрений. Дополнительная плашка не появляется.',symbol:'check',amount:2500,recipient:'Дмитрий С.',sender:'Дмитрий',balance:186350,messages:['Верни, пожалуйста, 2 500 ₽ за общий ужин.'],result:'Нет сигнала антифрода',intro:'Перевод проходит обычным путём.',findings:[]};
const stageList=[['transfer','Перевод'],['blocked','Предупреждение'],['upload','ИИ-ассистент'],['result','Разбор ситуации'],['done','Решение и помощь']];
let state={scenario:'job',screen:'home',amount:12000,method:'image',source:null,text:'',file:null,fileUrl:null,outcome:null,reviewed:false,ownMaterial:false,supportMessages:[],handoff:null,staffAnswer:null,skipped:false,analysisTimer:null};
let modalReturn=null,toastTimer;
const current=()=>scenarios[state.scenario];
const actualResult=()=>state.source==='external'?scenarios.unclear:current();
const resultKey=()=>state.source==='external'?'unclear':state.scenario;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function releaseFile(){if(state.fileUrl)URL.revokeObjectURL(state.fileUrl);state.fileUrl=null;state.file=null}
function reset(scenario=state.scenario){clearTimeout(state.analysisTimer);releaseFile();state={...state,scenario,screen:'home',amount:scenarios[scenario].amount,method:'image',source:null,text:'',outcome:null,reviewed:false,ownMaterial:false,supportMessages:[],handoff:null,staffAnswer:null,skipped:false,analysisToken:null};render()}
function go(screen){
  clearTimeout(state.analysisTimer);state.analysisToken=null;
  if(screen==='transfer'&&['sent','cancel'].includes(state.outcome)){releaseFile();clearAssessment();state.source=null;state.text='';state.outcome=null;state.skipped=false;state.ownMaterial=false;state.amount=current().amount;}
  if(state.scenario==='normal'&&['blocked','upload','analysis','result','repeat'].includes(screen))screen='confirm';
  state.screen=screen;render();
}
function clearAssessment(){state.reviewed=false;state.handoff=null;state.staffAnswer=null;state.supportMessages=[]}
function chooseSample(){releaseFile();clearAssessment();state.ownMaterial=false;state.source='sample';state.text=current().messages.join('\n')}
function completeAssessment(){
  state.reviewed=true;
  if(['job','unclear'].includes(state.scenario)&&!state.handoff)state.handoff=state.scenario==='job'?'risk':'uncertain';
}

function header(title,back='home',right=''){return `<header class="screen-header"><button class="icon-button" data-action="go" data-screen="${back}" aria-label="Назад">${icon('back')}</button><h2>${title}</h2>${right}</header>`}
function btn(text,action,cls='primary',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`}
function transferSummary(){return `<div class="check-summary"><span class="round-icon gray">${esc(current().recipient[0])}</span><div class="grow"><div class="small-title">${esc(current().recipient)}</div><div class="small-sub">По номеру телефона · СБП</div></div><span class="amount-small">${money(state.amount)}</span></div>`}
function bottomNav(active='home'){return `<nav class="bottom-nav" aria-label="Навигация банка">${[['home','Главная','home'],['repeat','Платежи','payments'],['wallet','Продукты','products'],['clock','История','history'],['chat','Чат','support']].map(([i,t,s])=>`<button class="nav-item ${active===s?'active':''}" data-action="go" data-screen="${s}">${icon(i)}<span>${t}</span></button>`).join('')}</nav>`}
function home(){return `<div class="screen-content home-content aurora-home"><section class="aurora-hero"><div class="home-header"><span class="avatar">К</span><button class="icon-button white-icon" data-action="security" aria-label="Безопасность">${icon('shield')}</button><span class="home-name">Клиент</span><button class="icon-button white-icon" data-action="notifications" aria-label="Уведомления">${icon('bell')}</button></div><div class="hero-balance"><div class="balance-label">Мастер-счёт в рублях ${icon('chevron')}</div><div class="balance-number">186 350<span>,50 ₽</span></div><div class="hero-tiles"><button data-action="topup">${icon('plus')} Пополнить счёт</button><button data-action="go" data-screen="products" class="all-products">Все мои счета<br>и продукты ${icon('wallet')}</button><button data-action="grow">${icon('spark')} Расти с ВТБ</button></div><button class="antiscam-banner" data-action="go" data-screen="transfer"><div><strong>Перевод под защитой</strong><p>Разберитесь в ситуации<br>до отправки денег</p><span>Попробовать ${icon('arrow')}</span></div><div class="shield-art">${icon('shield')}</div></button></div></section><section class="home-white-panel"><div class="home-section-title">Платежи и переводы <span>⌃</span></div><div class="quick-actions">${[['repeat','Клиенту<br>ВТБ','transfer'],['arrow','В другой<br>банк','transfer'],['qr','QR и оплата<br>по фото','qr'],['phone','Мобильная<br>связь','mobile']].map(([i,t,a],n)=>`<button class="quick-action pastel-${n}" data-action="${a==='transfer'?'go':a}" ${a==='transfer'?'data-screen="transfer"':''}><span>${icon(i)}</span>${t}</button>`).join('')}</div><div class="home-section-title small">Частые операции <span>⌃</span></div><div class="frequent-contacts"><button data-action="go" data-screen="transfer"><span>АК</span>Алексей</button><button data-action="go" data-screen="transfer"><span>ИМ</span>Ирина</button><button data-action="go" data-screen="transfer"><span>${icon('plus')}</span>Перевести</button></div><button class="home-row card" data-action="go" data-screen="history"><span class="round-icon">${icon('clock')}</span><span><strong>История операций</strong><small>Расходы и поступления</small></span>${icon('chevron')}</button></section></div>${bottomNav()}`}
function payments(){return `${header('Платежи','home',`<button class="icon-button" data-action="qr" aria-label="QR-код">${icon('qr')}</button>`)}<div class="screen-content"><div class="card"><h1 style="font-size:24px">Перевести</h1><button class="search-box" style="background:#f4f6f9" data-action="go" data-screen="transfer">${icon('search')} Телефон, карта или счёт ${icon('qr')}</button><div class="quick-actions">${[['repeat','Между<br>счетами'],['wallet','По номеру<br>карты'],['plus','Из другого<br>банка'],['file','По<br>реквизитам']].map(([i,t],n)=>`<button class="quick-action pastel-${n}" data-action="go" data-screen="transfer"><span>${icon(i)}</span>${t}</button>`).join('')}</div></div><button class="home-promo" style="width:100%;text-align:left" data-action="go" data-screen="upload"><div><strong>Сомневаетесь в переводе?</strong><p>Проверьте переписку<br>с помощником Антискам</p></div><span class="shield-art">${icon('shield')}</span></button><div class="section-label">Регулярные платежи</div><button class="home-row card" data-action="mobile"><span class="round-icon">${icon('phone')}</span><span><strong>Мобильная связь</strong><small>Оплата телефона</small></span>${icon('chevron')}</button><button class="home-row card" data-action="templates"><span class="round-icon">${icon('file')}</span><span><strong>Шаблоны и автоплатежи</strong><small>Платежи по расписанию</small></span>${icon('chevron')}</button></div>${bottomNav('payments')}`}
function transfer(){return `${header('Перевод по телефону','home')}<div class="screen-content"><div class="card"><label class="field">Телефон получателя<input aria-label="Демонстрационный телефон получателя" value="+7 (•••) •••-24-68" readonly></label><div class="divider"></div><div class="inline"><span class="round-icon">${esc(current().recipient[0])}</span><div class="grow"><div class="small-title">${esc(current().recipient)}</div><div class="small-sub">Другой банк · СБП</div></div><span class="chip">Демо</span></div></div><div class="card"><label class="field">Сумма перевода<div class="amount-field"><input class="amount-input" id="amount" type="text" inputmode="numeric" autocomplete="off" value="${state.amount}" aria-label="Сумма перевода"><span>₽</span></div></label><div id="amount-error" class="form-error" role="alert"></div><div class="divider"></div><div class="row-between"><span>Комиссия</span><strong>Без комиссии</strong></div></div><div class="section-label">Счёт списания</div><div class="card inline"><span class="mini-card">ВТБ</span><div class="grow"><div class="small-title">Мастер-счёт</div><div class="small-sub">186 350,50 ₽ · •• 4028</div></div>${icon('chevron')}</div><div class="callout neutral">${icon('info')}<span>Вы переводите деньги физическому лицу. Проверьте имя получателя перед оплатой.</span></div></div><footer class="screen-footer">${btn('Продолжить','review')}<p class="footer-small">Демонстрационные данные. Реального списания нет.</p></footer>`}
function confirm(repeat=false){return `${header(repeat?'Подтвердите перевод':'Проверьте перевод',repeat?'blocked':'transfer')}<div class="screen-content white"><div class="result-emblem blue">${icon(repeat?'repeat':'arrow')}</div><h1>${money(state.amount)}</h1><p class="body-copy">${repeat?'Вы продолжаете перевод с теми же реквизитами и суммой.':'Перевод по номеру телефона'}</p>${transferSummary()}<div class="row-between"><span>Счёт списания</span><strong>Мастер-счёт · •• 4028</strong></div><div class="row-between"><span>Комиссия</span><strong>0 ₽</strong></div><div class="divider"></div>${repeat?`<div class="callout amber">${icon('info')}<span>Проверка переписки не гарантирует безопасность сделки. Продолжайте только после независимой проверки.</span></div><p class="tiny muted">В этом демосценарии нет обязательного периода охлаждения. При наличии такого основания банк укажет срок и доступные действия.</p>`:`<p class="body-copy">Убедитесь, что получатель и сумма совпадают с вашей договорённостью.</p>`}</div><footer class="screen-footer">${btn(repeat?'Подтвердить · '+money(state.amount):'Перевести '+money(state.amount),repeat?'send-demo':'attempt')}${btn('Вернуться','go','link-action',`data-screen="${repeat?'blocked':'transfer'}"`)}</footer>`}
function blocked(){return `${header('Проверка перевода','transfer')}<div class="screen-content white"><div class="result-emblem">${icon('alert')}</div><h1>Давайте проверим<br>этот перевод</h1><p class="body-copy">Банк заметил необычную операцию: новый получатель и непривычная сумма. Деньги пока на вашем счёте.</p>${transferSummary()}<div class="card check-invite"><div class="evidence-heading">${icon('shield')} ВТБ Антискам</div><h3>Расскажите, что происходит</h3><p class="body-copy" style="margin-bottom:0">Можно голосом, текстом или скриншотом. Если есть риск или не хватает информации, помощник подключит сотрудника.</p></div>${btn('Сразу связаться с сотрудником','go','link-action','data-screen="support"')}<p class="tiny muted">Помощь добровольная. Пропуск возвращает к подтверждению перевода и не отменяет обязательные ограничения банка.</p></div><footer class="screen-footer">${btn('Разобраться с помощником','go','primary','data-screen="upload"')}${btn('Пропустить и продолжить','skip','secondary')}${btn('Не переводить','cancel','link-action')}</footer>`}
function samplePreview(){return `<div class="attached-head"><span>Пример переписки · ${current().messages.length} сообщения</span><button data-action="remove-file">Удалить</button></div><div class="chat-preview"><div class="chat-preview-top"><span class="avatar" style="height:24px;width:24px;font-size:10px">${esc(current().sender[0])}</span>${esc(current().sender)}<span class="chip" style="margin-left:auto">Демо</span></div>${current().messages.map((m,i)=>`<div class="bubble ${state.scenario==='purchase'&&i===0?'mine':''}">${esc(m)}</div>`).join('')}</div>`}
const sampleStories={
  job:'Мне обещают выплатить 36 000 рублей за работу. Но сначала нужно отправить 12 000. Менеджер торопит и просит сказать банку, что я возвращаю долг. Что делать?',
  purchase:'Я покупаю товар за 48 000 рублей. Договорились встретиться, осмотреть его и только потом оплатить продавцу. Почему банк обратил внимание на перевод?',
  unclear:'Мне прислали реквизиты и попросили перевести 25 000 рублей. В этих сообщениях больше ничего нет. Помогите понять, что нужно проверить.'
};
function upload(){
  const ownVisible=state.ownMaterial||state.source==='external';
  const voice=state.method==='voice';
  const title=voice?'Пример голосового сообщения':state.method==='text'?'Пример сообщения помощнику':'Добавить переписку из примера';
  return `${header('ИИ-помощник','blocked',`<button class="icon-button" data-action="privacy" aria-label="Как обрабатываются материалы">${icon('info')}</button>`)}
  <div class="screen-content"><div class="small-label">${icon('shield')} ВТБ АНТИСКАМ</div>
  <h1>Расскажите,<br>что происходит</h1><p class="body-copy">Кто попросил перевести деньги и зачем? Помогу разобраться. Если потребуется, подключу сотрудника банка.</p>
  <div class="method-tabs assistant-methods" role="group" aria-label="Как рассказать о ситуации">${[['voice','mic','Голосом'],['text','edit','Текстом'],['image','image','Скриншот']].map(([m,i,t])=>`<button class="method-tab ${state.method===m?'active':''}" data-action="method" data-method="${m}" aria-pressed="${state.method===m}">${icon(i)} ${t}</button>`).join('')}</div>
  ${state.source==='sample'?(state.method==='image'?samplePreview():`<div class="card story-preview"><div class="small-label">${icon(voice?'mic':'chat')} ${voice?'РАСШИФРОВКА · ДЕМО':'ВАШЕ СООБЩЕНИЕ · ДЕМО'}</div><p>${esc(sampleStories[state.scenario]||current().context)}</p><button class="text-button" data-action="remove-file">Удалить</button></div>`):`<button class="example-button ready-example ${voice?'voice-example':''}" data-action="sample">${icon(voice?'mic':state.method==='text'?'edit':'image')}<span><strong>${title}</strong><small>${esc(current().name)} · готовый пример</small></span>${icon('chevron')}</button>`}
  ${voice?'<p class="tiny muted">В демо показана готовая расшифровка. Микрофон не включается.</p>':''}
  ${state.source==='sample'?`<div class="sample-ready">${icon('check')} Контекст добавлен. Можно посмотреть ответ помощника.</div>`:''}
  ${!voice?`<button class="own-material-toggle" data-action="own-material" aria-expanded="${!!ownVisible}">${icon(state.method==='image'?'image':'edit')} ${ownVisible?'Скрыть свой материал':state.method==='image'?'Или добавить своё фото / скриншот':'Или написать своё сообщение'} ${icon('chevron')}</button>`:''}
  ${ownVisible&&!voice?`<div class="own-material"><div class="callout neutral">${icon('info')}<span>Свой материал можно добавить. ИИ-анализ в прототипе не подключён.</span></div>
  ${state.method==='image'?`<label class="upload-box" tabindex="0" role="button" aria-label="Добавить скриншот" id="upload-target">${icon('plus')}<strong>Выбрать фото или скриншот</strong><small>PNG, JPG или WebP · до 10 МБ</small><input type="file" id="file-input" accept="image/png,image/jpeg,image/webp"></label>`:`<div class="card"><textarea id="message-text" placeholder="Расскажите, кто попросил перевести деньги и зачем…" aria-label="Сообщение ИИ-помощнику">${state.source==='sample'?'':esc(state.text)}</textarea></div>`}
  ${state.file?`<div class="attached-head"><span>Файл добавлен</span><button data-action="remove-file">Удалить</button></div><div class="file-preview"><img src="${state.fileUrl}" alt="Выбранный скриншот"><div><strong class="file-name">${esc(state.file.name)}</strong><div class="small-sub">Остаётся только в браузере</div></div></div>`:''}</div>`:''}
  <div class="privacy-note">${icon('lock')}<span>Материалы остаются в браузере. Ответы ИИ и сотрудника в демо подготовлены заранее.</span></div></div>
  <footer class="screen-footer">${btn(state.source==='external'?'Продолжить демонстрацию':'Показать ответ помощника','analyze','primary',!state.source?'disabled':'')}${btn('Связаться с сотрудником','go','secondary','data-screen="support"')}${btn('Пропустить и продолжить','skip','link-action')}</footer>`;
}
function analysis(){return `${header('Разбираемся в ситуации','upload')}<div class="analysis-content"><div class="analysis-orb">${icon('shield')}</div><h1>Посмотрим<br>на ситуацию целиком</h1><p>Сообщения, получатель<br>и параметры перевода</p><div class="analysis-steps"><div class="analysis-step current">${icon('check')} Учитываем ваш рассказ</div><div class="analysis-step" id="analysis-step-2">${icon('clock')} Сопоставляем с переводом</div><div class="analysis-step" id="analysis-step-3">${icon('clock')} Проверяем, нужна ли помощь сотрудника</div></div><p class="analysis-demo">Демонстрация анализа · без отправки данных</p></div>`}
function questions(){if(resultKey()==='job')return `<p>Не отправляйте новый платёж для получения обещанной выплаты.</p><div class="question-card"><b>Проверка работодателя</b>Свяжитесь с компанией по контактам, которые найдёте независимо от собеседника. Уточните, работает ли у них этот человек и предусмотрена ли такая выплата.</div><div class="question-card"><b>Если звонят из банка</b>Завершите разговор и сами обратитесь через банковское приложение. Не используйте номер или ссылку, присланные собеседником.</div>`;if(resultKey()==='purchase')return `<div class="question-card"><b>Что спросить продавца</b>«Можно осмотреть товар и оплатить при получении?»</div><div class="question-card"><b>Что проверить на встрече</b>Осмотрите товар и сверьте имя получателя. Убедительный ответ в переписке сам по себе не подтверждает честность продавца.</div>`;return `<div class="question-card"><b>Что уточнить</b>За что вы платите? Кто предложил перевод? Как вы получили реквизиты?</div><div class="question-card"><b>Если просит знакомый</b>Свяжитесь с ним по ранее сохранённому номеру. Не полагайтесь только на имя и фотографию в мессенджере.</div>`}
const storyQuotes={job:['«Но сначала нужно отправить 12 000»','«Просит сказать банку, что я возвращаю долг»','«Менеджер торопит»'],purchase:['«Осмотреть его и только потом оплатить продавцу»','«Я покупаю товар за 48 000 рублей»'],unclear:['«Прислали реквизиты и попросили перевести 25 000 рублей»']};
function visibleFindings(){
 const findings=actualResult().findings;
 if(state.method==='image')return findings;
 return findings.map(([title,quote,explanation],i)=>state.scenario==='purchase'&&i===1?['Получателя нужно сверить',storyQuotes.purchase[i],'В рассказе не назван продавец. Сверьте его имя с получателем перевода.']:[title,storyQuotes[state.scenario]?.[i]||quote,explanation]);
}
function result(){
  if(state.source==='external')return externalMaterial();
  const d=actualResult(),key=resultKey(),needsStaff=!!state.handoff;
  return `${header('Ответ помощника','upload')}<div class="screen-content"><div class="small-label">${icon('spark')} ИИ-ПОМОЩНИК · ДЕМО</div><div class="result-emblem ${key==='job'?'':key==='purchase'?'blue':'gray'}" style="width:51px;height:51px;border-radius:17px;margin:0 0 16px">${icon(key==='job'?'alert':'info')}</div><h1 class="result-title">${d.result}</h1><p class="body-copy">${d.intro}</p>
  ${needsStaff?`<div class="staff-handoff"><div class="evidence-heading">${icon('chat')} Подключён сотрудник · демо</div><p>${key==='job'?'Вижу признаки обмана.':'Мне не хватает данных для вывода.'} Передал ситуацию сотруднику ВТБ Онлайн. Он задаст вопросы и проверит, верно ли я понял ситуацию.</p><span class="tiny muted">Переданы сумма, получатель, выбранные материалы и мой разбор.</span></div>`:''}
  ${visibleFindings().map(([t,q,e])=>`<div class="finding ${key!=='job'?'neutral':''}"><div class="finding-title"><span class="finding-dot"></span>${t}</div><blockquote>${q}</blockquote><p>${e}</p></div>`).join('')}
  ${key!=='unclear'?`<div class="transfer-match">${icon('wallet')}<span>${key==='job'?'В сообщениях запрашивают '+money(current().amount)+'. Ваш перевод: '+money(state.amount)+' получателю '+esc(current().recipient)+'.':state.method==='image'?'Имя в сообщении совпадает с указанным в переводе. Это дополнительный сигнал, а не подтверждение безопасности.':'В переводе указан '+esc(current().recipient)+'. Сверьте имя с продавцом до оплаты.'}</span></div>`:''}<details class="accordion"><summary>Что можно проверить самостоятельно${icon('chevron')}</summary><div class="accordion-body">${questions()}</div></details><p class="tiny muted" style="margin:16px 1px 0">Это предварительная оценка. Сотрудник может её уточнить или исправить. Обязательные ограничения банка действуют отдельно.</p></div>
  <footer class="screen-footer">${needsStaff?`${btn('Открыть чат с сотрудником','go','primary','data-screen="support"')}${btn(key==='job'?'Не переводить':'Добавить информацию',key==='job'?'cancel':'go','secondary',key==='unclear'?'data-screen="upload"':'')}${btn('К подтверждению перевода','go','link-action','data-screen="repeat"')}`:`${btn('К подтверждению перевода','go','primary','data-screen="repeat"')}${btn('Проверить со сотрудником','go','secondary','data-screen="support"')}${btn('Сохранить на потом','save','link-action')}`}</footer>`;
}
function done(){const sent=state.outcome==='sent',saved=state.outcome==='saved';return `${header('Перевод','home')}<div class="screen-content white success-center"><div class="result-emblem ${sent?'blue':saved?'gray':'green'}">${icon(sent?'check':saved?'clock':'shield')}</div><h1>${sent?'Перевод выполнен':saved?'Перевод сохранён':'Вы отказались<br>от перевода'}</h1><p class="body-copy">${sent?'Демонстрационная операция.<br>Реальные деньги не отправлялись.':saved?'Деньги остаются на счёте.<br>Вернуться можно из истории операций.':money(state.amount)+' остались на вашем счёте.<br>Деньги не отправлены.'}</p><div class="receipt"><div class="inline"><span class="round-icon gray">${esc(current().recipient[0])}</span><div><div class="small-title">${esc(current().recipient)}</div><div class="small-sub">Перевод по СБП</div></div></div><div class="divider"></div><div class="row-between"><span>Сумма</span><strong>${money(state.amount)}</strong></div><div class="row-between"><span>Статус</span><strong>${sent?'Выполнен · демо':saved?'Черновик':'Отменён'}</strong></div></div>${!sent&&!saved?`<div class="callout neutral" style="margin-top:17px;text-align:left">${icon('info')}<span>Если вы уже сообщали коды или данные карты, обратитесь в банк.</span></div>`:''}</div><footer class="screen-footer">${btn('На главный экран','go','primary','data-screen="home"')}${btn(saved?'Вернуться к переводу':'Обсудить с банком','go','secondary',`data-screen="${saved?'blocked':'support'}"`)}</footer>`}
const staffChecks={
  job:{question:'Помощник заметил риск. Я проверю его вывод. Вас просят сначала заплатить, чтобы получить заработанные деньги, и назвать банку другую цель перевода?',options:[['risk','Да, требуют платёж и просят назвать его возвратом долга']],replies:{risk:'Спасибо, что уточнили. В этом примере вы подтвердили требование оплаты ради выплаты и просьбу скрыть цель. Вывод помощника обоснован. Не переводите деньги и прекратите общение с этим собеседником. Помогу отменить перевод.'}},
  unclear:{question:'Помощник не смог понять цель платежа. Сам по себе короткий фрагмент ещё не означает обман. Кому и за что вы переводите? Проверяли просьбу по знакомому вам номеру?',options:[['verified','Возвращаю долг знакомой. Я сам позвонил ей по сохранённому номеру'],['risk','Незнакомый человек требует срочный платёж ради выплаты']],replies:{verified:'В этом примере мы уточнили цель перевода и способ проверки получателя. Основание для подозрения не подтвердилось: это возврат долга знакомой, а переписка была неполной. Уточняю оценку помощника. Можно вернуться к подтверждению; банковские проверки сохраняются.',risk:'Теперь понятно, почему нужен платёж. Требование сначала отправить деньги ради обещанной выплаты указывает на риск обмана. Рекомендую отменить перевод. Вам не нужно выполнять просьбу собеседника прямо сейчас.'}},
  purchase:{question:'Помощник не увидел явных признаков обмана. Это тоже нужно проверить. Вы уже осмотрели товар? Он у продавца, а имя получателя совпадает с договорённостью?',options:[['verified','Да, я на встрече, осмотрел товар и сверил получателя'],['risk','Нет, теперь продавец требует предоплату до встречи']],replies:{verified:'В этом примере мы уточнили обстоятельства: вы на встрече, товар осмотрели, имя получателя сверили. Причина первоначального сигнала банка не подтвердилась. Можно вернуться к подтверждению перевода. Это не гарантия качества сделки.',risk:'Тогда обстоятельства изменились. Помощник оценивал оплату после осмотра, а теперь от вас требуют предоплату. Исправляю рекомендацию: сначала проверьте товар и продавца, сейчас деньги лучше не отправлять.'}}
};
function staffReply(check){
  const reply=check.replies[state.staffAnswer];
  if(state.reviewed)return reply;
  return reply.replace('Вывод помощника обоснован. ','Эти обстоятельства указывают на риск обмана. ').replace('Уточняю оценку помощника. ','').replace('Помощник оценивал оплату после осмотра, а теперь от вас требуют предоплату. Исправляю рекомендацию:','Изначально речь шла об оплате после осмотра, а теперь от вас требуют предоплату. Рекомендую:');
}
function support(){
  const check=state.source!=='external'&&!['sent','cancel'].includes(state.outcome)?staffChecks[state.scenario]:null;
  const answer=check?.options.find(([id])=>id===state.staffAnswer);
  const sent=['sent','cancel'].includes(state.outcome);
  const status=state.outcome==='sent'?'В демосценарии перевод уже выполнен.':state.outcome==='cancel'?'Перевод отменён, деньги остались на счёте.':'Деньги пока не отправлены.';
  return `${header('Сотрудник ВТБ Онлайн',sent?'done':state.reviewed?'result':state.scenario==='normal'?'home':'blocked','<span class="chip">Демо</span>')}<div class="screen-content chat-support">
  <div class="support-date">${state.handoff?'Обращение создал ИИ-помощник':'Вы обратились к сотруднику'}</div>
  <div class="support-context"><div class="evidence-heading">${icon('file')} Контекст обращения</div><p>${money(state.amount)} · ${esc(current().recipient)}</p><div class="context-copy">${state.reviewed&&state.source==='sample'?`Предварительный вывод ИИ: ${current().result.replace(/<br>/g,' ').toLowerCase()}.<br>Приложены: ${state.method==='voice'?'расшифровка рассказа':state.method==='text'?'сообщение клиента':'выбранная переписка'} и объяснение ИИ.<details class="staff-materials"><summary>Посмотреть переданный контекст</summary><p>${esc(state.method==='image'?current().messages.join(' '):sampleStories[state.scenario])}</p><p>${esc(current().intro)}</p></details>`:state.source==='external'?'Добавлен свой материал. Его содержание в демо не анализировалось.':'ИИ-разбора пока нет. Сотрудник уточнит обстоятельства сам.'}</div></div>
  <div class="support-bubble"><div class="small-sub">Анна · сотрудник · демо-ответ</div>Здравствуйте! ${status} ${check?(state.reviewed?check.question:check.question.replace('Помощник заметил риск. Я проверю его вывод. ','Я уточню обстоятельства. ').replace('Помощник не смог понять цель платежа. ','Давайте уточним цель платежа. ').replace('Помощник не увидел явных признаков обмана. Это тоже нужно проверить. ','Давайте проверим обстоятельства покупки. ')):'Я помогу проверить ситуацию. Расскажите, кто попросил перевод и зачем. В этом прототипе произвольные сообщения не обрабатываются сотрудником.'}</div>
  ${check&&!answer?`<div class="staff-options"><div class="small-label">ВЫБЕРИТЕ ОТВЕТ КЛИЕНТА ДЛЯ ДЕМО</div>${check.options.map(([id,label])=>btn(label,'staff-answer','staff-option',`data-answer="${id}"`)).join('')}</div>`:''}
  ${answer?`<div class="support-bubble self">${esc(answer[1])}</div><div class="support-bubble staff-verdict"><div class="small-sub">Анна · проверила обстоятельства · демо</div>${staffReply(check)}</div><div class="staff-next">${btn(state.staffAnswer==='risk'?'Не переводить':'К подтверждению перевода',state.staffAnswer==='risk'?'cancel':'go','primary',state.staffAnswer==='verified'?'data-screen="repeat"':'')}${btn('Выбрать другой ответ в демо','staff-reset','link-action')}</div>`:''}
  ${state.supportMessages.map(m=>`<div class="support-bubble self">${esc(m)}</div><div class="support-bubble"><span class="small-sub">Примечание к демо</span><br>Сообщение добавлено только на этом экране. Реальный сотрудник не подключён и не прочитает его. ${check&&!answer?'Выберите готовый ответ выше, чтобы увидеть продолжение.':'Проверка произвольного текста в прототипе не выполняется.'}</div>`).join('')}
  <div class="callout neutral" style="margin-top:10px">${icon('info')}<span>Это пример работы сотрудника. Диалог и выводы подготовлены заранее, сообщения в банк не отправляются.</span></div></div>
  <footer class="screen-footer"><form id="support-form" class="support-compose"><input id="support-input" placeholder="Написать сообщение · демо" aria-label="Демонстрационное сообщение поддержке" autocomplete="off"><button type="submit" aria-label="Отправить демосообщение">${icon('send')}</button></form>${!sent?btn('Вернуться к переводу','go','link-action',`data-screen="${state.scenario==='normal'?'confirm':'repeat'}"`):''}</footer>`;
}
function history(){const labels={saved:'Черновик перевода · продолжить',sent:'Выполнен · демо',cancel:'Отменён · деньги не отправлены',pending:'Перевод не выполнен · проверить'};const target=['sent','cancel'].includes(state.outcome)?'done':'blocked';return `${header('История операций','home')}<div class="screen-content"><div class="section-label">Сегодня</div>${state.outcome?`<button class="home-row card" data-action="go" data-screen="${target}"><span class="round-icon">${icon(state.outcome==='saved'?'clock':state.outcome==='sent'?'check':'shield')}</span><span><strong>${esc(current().recipient)} · ${money(state.amount)}</strong><small>${labels[state.outcome]}</small></span>${icon('chevron')}</button>`:`<div class="card"><p class="body-copy" style="margin:0">Сегодня операций пока нет</p></div>`}<div class="section-label">Вчера</div><div class="card inline"><span class="round-icon gray">${icon('wallet')}</span><div class="grow"><div class="small-title">Супермаркет</div><div class="small-sub">Продукты · демо</div></div><span class="small-title">−1 286 ₽</span></div></div>${bottomNav('history')}`}
function products(){return `${header('Мои счета и продукты','home')}<div class="screen-content"><div class="card"><div class="balance-label">Мастер-счёт в рублях</div><div class="balance-number">186 350<span style="font-size:20px">,50 ₽</span></div><div class="inline"><span class="mini-card">ВТБ</span><span class="tiny muted">Карта •• 4028</span><span class="mir-card">МИР</span></div></div><div class="callout">${icon('info')}<span>Счета и операции в этом прототипе демонстрационные.</span></div>${btn('Перевести деньги','go','primary','data-screen="transfer"')}</div>${bottomNav('products')}`}
const insights={
  home:['01','Помощь внутри<br>банковского приложения','Проверка дополняет привычный перевод, когда антифрод замечает подозрение.','Нет сигнала антифрода, нет дополнительной плашки.'],
  transfer:['01','Обычный путь<br>перевода','Клиент указывает получателя и сумму. Антифрод проверяет операцию перед отправкой.','В демо сигнал ML задан сценарием.'],
  confirm:['01','Реквизиты<br>перед оплатой','Клиент видит сумму и имя получателя до подтверждения.','Все операции в прототипе демонстрационные.'],
  blocked:['02','ML заметил<br>подозрение','Только теперь появляется плашка. Клиент может открыть помощника, обратиться к сотруднику или пропустить.','Помощь добровольная, кнопка пропуска видна сразу.'],
  upload:['03','Рассказать удобным<br>способом','Голос, сообщение или фото дополняют данные перевода. ИИ разбирается в ситуации, а не просто проверяет реквизиты.','В демо используются готовые ответы и расшифровка голоса.'],
  analysis:['03','Контекст +<br>банковский сигнал','ИИ сопоставляет рассказ клиента с суммой, получателем и сигналом антифрода.','При риске или неопределённости подключается сотрудник.'],
  result:['04','ИИ объясняет<br>свой вывод','При признаках обмана или нехватке данных помощник сам создаёт обращение сотруднику.','Оценку ИИ можно проверить и исправить.'],
  repeat:['04','Решение<br>остаётся за клиентом','После пропуска или консультации клиент возвращается к подтверждению той же суммы и получателя.','Обязательные ограничения банка действуют отдельно.'],
  done:['05','Понятный итог<br>для клиента','Клиент видит, выполнен ли перевод и что произошло с деньгами.','В прототипе реальные деньги не отправляются.'],
  support:['05','Сотрудник<br>проверяет ИИ','Сотрудник ВТБ Онлайн получает контекст, уточняет факты и делает свой вывод. Он может исправить рекомендацию помощника.','Показан подготовленный диалог, реальный сотрудник не подключён.'],
  payments:['01','Знакомые<br>платежи и переводы','Помощника можно открыть самостоятельно, если просьба вызывает сомнения.','Автоматическая плашка появляется только по сигналу ML.'],
  products:['01','Привычные<br>счета и продукты','Основной банковский интерфейс остаётся узнаваемым.','Здесь используются демонстрационные данные.'],
  history:['05','Вернуться<br>к операции','История показывает статус перевода и сохранённые черновики.','Перед отправкой банк проверяет операцию.']
};
function render(){const screens={home,transfer,confirm:()=>confirm(false),repeat:()=>confirm(true),blocked,upload,analysis,result,done,support,payments,products,history};$('#app').innerHTML=(screens[state.screen]||home)();$('#app').classList.remove('screen-enter');void $('#app').offsetWidth;$('#app').classList.add('screen-enter');$('.device').classList.toggle('home-device',state.screen==='home');$('#scenario-buttons').innerHTML=Object.entries(scenarios).map(([k,v])=>`<button class="scenario-button ${state.scenario===k?'active':''}" data-action="scenario" data-scenario="${k}" aria-pressed="${state.scenario===k}"><span class="scenario-symbol">${icon(v.symbol)}</span><span><strong class="desktop-scenario">${v.name}</strong><strong class="mobile-scenario">${v.short}</strong><small>${v.sub}</small></span><span class="radio"></span></button>`).join('');const group={home:'transfer',confirm:'transfer',repeat:'result',analysis:'upload',support:'done',payments:'transfer',products:'transfer',history:'done'};const visibleStages=state.scenario==='normal'?[['transfer','Перевод'],['done','Результат']]:stageList;const active=visibleStages.findIndex(([s])=>s===(group[state.screen]||state.screen));$('#steps').innerHTML=visibleStages.map(([s,t],i)=>`<button class="step ${active===i?'active':active>i?'done':''}" data-action="jump" data-screen="${s}" ${active===i?'aria-current="step"':''}><span class="step-dot">${active>i?icon('check'):i+1}</span>${t}</button>`).join('');const inf=state.scenario==='normal'?['01','Нет сигнала,<br>нет плашки','Антифрод не заметил подозрений. Перевод проходит обычным путём, без ИИ-ассистента.','Отсутствие сигнала не является гарантией безопасности.']:state.screen==='result'&&state.source==='external'?['04','Загрузка без<br>оценки содержания','Собственный материал можно добавить, но модель в этой демонстрации не подключена.','Подготовленные примеры показывают предполагаемый результат работы сервиса.']:(insights[state.screen]||insights.home);$('#insight').innerHTML=`<div class="insight-number">${inf[0]}</div><h2>${inf[1]}</h2><p>${inf[2]}</p><div class="insight-rule"></div><div class="design-principle">${icon('check')}<span>${inf[3]}</span></div>`;$('#device-caption').textContent=state.screen==='home'?'Нажмите «В другой банк», чтобы начать':state.screen==='result'?(state.source==='external'?'Выберите готовый пример, чтобы увидеть разбор':'Прокрутите экран, чтобы увидеть весь разбор'):'Можно нажимать кнопки и прокручивать экран телефона';renderGuide();if(state.screen==='upload')bindUpload();if(state.screen==='support')$('#support-form').addEventListener('submit',e=>{e.preventDefault();const text=$('#support-input').value.trim();if(!text)return;state.supportMessages.push(text);render();$('.screen-content').scrollTop=$('.screen-content').scrollHeight;toast('Демосообщение добавлено. В банк оно не отправлено.')});}
function bindUpload(){const fileInput=$('#file-input');if(fileInput){fileInput.addEventListener('change',()=>{const f=fileInput.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>10*1024*1024){toast('Выберите PNG, JPG или WebP до 10 МБ');fileInput.value='';return}releaseFile();clearAssessment();state.file=f;state.fileUrl=URL.createObjectURL(f);state.source='external';render()});$('#upload-target').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fileInput.click()}})}const ta=$('#message-text');if(ta)ta.addEventListener('input',()=>{clearAssessment();state.text=ta.value;state.source=ta.value.trim()?'external':null;const b=$('[data-action="analyze"]');b.disabled=!state.source;b.textContent=state.source==='external'?'Продолжить демонстрацию':'Показать ответ помощника';const note=$('.privacy-note span');if(note)note.textContent='Текст остаётся в браузере. ИИ-анализ собственных материалов в этой версии не подключён.'})}
function modal(title,body){modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div>${body}${btn('Понятно','close-modal')}</section></div>`;$('#modal-root button').focus()}
function closeModal(){$('#modal-root').innerHTML='';if(modalReturn?.isConnected)modalReturn.focus()}
function startAnalysis(){
  if(!state.source)return;
  if(state.source==='external'){go('result');return;}
  go('analysis');const token={};state.analysisToken=token;
  setTimeout(()=>{if(state.screen!=='analysis'||state.analysisToken!==token)return;const el=$('#analysis-step-2');el.classList.add('current');el.innerHTML=icon('check')+' Сопоставляем с переводом'},650);
  setTimeout(()=>{if(state.screen!=='analysis'||state.analysisToken!==token)return;const el=$('#analysis-step-3');el.classList.add('current');el.innerHTML=icon('check')+' Проверяем, нужна ли помощь сотрудника'},1200);
  state.analysisTimer=setTimeout(()=>{if(state.screen!=='analysis'||state.analysisToken!==token)return;completeAssessment();go('result')},1850);
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(a==='start-demo')startDemo(b.dataset.scenario||'job');else if(a==='demo-overview')showOverview();else if(a==='demo-finish')showDemoSummary();else if(a==='own-material'){state.ownMaterial=!state.ownMaterial;clearAssessment();if(state.ownMaterial&&state.source==='sample'){state.source=null;state.text='';}if(!state.ownMaterial&&state.source==='external'){releaseFile();state.source=null;state.text='';}render()}else if(a==='sample-result'){chooseSample();startAnalysis()}else if(a==='skip'){state.skipped=true;go('repeat')}else if(a==='staff-answer'){const check=staffChecks[state.scenario];if(state.source!=='external'&&check?.options.some(([id])=>id===b.dataset.answer)){state.staffAnswer=b.dataset.answer;render();$('.screen-content').scrollTop=$('.screen-content').scrollHeight}}else if(a==='staff-reset'){state.staffAnswer=null;render()}else if(a==='go')go(b.dataset.screen);else if(a==='restart')startDemo(state.scenario);else if(a==='scenario')startDemo(b.dataset.scenario);else if(a==='jump'){if(b.dataset.screen==='result'&&state.scenario!=='normal'){if(!state.source)chooseSample();if(state.source==='sample')completeAssessment()}if(b.dataset.screen==='done'&&(!state.outcome||state.outcome==='pending')){go(state.scenario==='normal'?'confirm':state.reviewed?'result':'blocked');return}go(b.dataset.screen)}else if(a==='review'){const value=Number($('#amount').value.replace(/[\s,]/g,''));if(!Number.isFinite(value)||value<1||value>186350){$('#amount-error').textContent='Введите сумму от 1 до 186 350 ₽';return}if(state.amount!==value)clearAssessment();state.amount=value;go('confirm')}else if(a==='attempt'){state.outcome=state.scenario==='normal'?'sent':'pending';go(state.scenario==='normal'?'done':'blocked')}else if(a==='send-demo'){state.outcome='sent';go('done')}else if(a==='cancel'){state.outcome='cancel';go('done')}else if(a==='save'){state.outcome='saved';go('done')}else if(a==='sample'){chooseSample();render()}else if(a==='remove-file'){releaseFile();clearAssessment();state.source=null;state.text='';render()}else if(a==='method'){if(state.method!==b.dataset.method){releaseFile();clearAssessment();state.source=null;state.text='';state.ownMaterial=false;}state.method=b.dataset.method;render()}else if(a==='analyze')startAnalysis();else if(a==='close-modal')closeModal();else if(a==='about')modal('О решении',`<h3>Что предлагаем внедрить</h3><p>ML-антифрод замечает необычный перевод и показывает плашку с кнопкой пропуска. Если сигнала нет, плашка не появляется. Клиент может рассказать ситуацию голосом, написать или добавить фото. ИИ сопоставляет контекст с переводом, а при риске или нехватке данных сам подключает сотрудника ВТБ Онлайн. Сотрудник уточняет обстоятельства и проверяет вывод ИИ, включая возможность ошибки.</p><h3>Что показывает демонстрация</h3><p>Пять шагов: перевод, предупреждение, добавление переписки, объяснение и решение клиента. Четыре примера показывают обычный перевод, подозрительную просьбу, покупку и нехватку данных. Голос показан готовой расшифровкой, микрофон не включается. Ответы сотрудника подготовлены заранее. ИИ-модель не подключена: собственные материалы можно загрузить, но их содержимое не анализируется.</p><p>Концепт сервиса «ВТБ Антискам» для кейса Changellenge Cup Moscow 2026. Это учебный UX-прототип, не приложение банка.</p><p>Все суммы, получатели, операции, ответы поддержки и результаты ИИ-проверки демонстрационные. Материалы остаются в вашем браузере и не передаются на сервер.</p><p>Визуальная основа: публичные экраны нового ВТБ Онлайн — aurora-шапка, мастер-счёт, круглые быстрые действия и тёмная нижняя навигация. Новые экраны Антискам разработаны для этого концепта. Системный шрифт использован вместо фирменного Omega UI.</p><ul><li><a href="https://www.rustore.ru/catalog/app/ru.vtb24.mobilebanking.android" target="_blank" rel="noopener noreferrer">ВТБ Онлайн — официальная карточка в RuStore</a></li><li><a href="https://workspace.ru/cases/redizayn-prilozheniya-vtb-onlayn-2/" target="_blank" rel="noopener noreferrer">Кейс редизайна, опубликованный ВТБ</a></li><li><a href="https://www.cbr.ru/faq/information_security/blokirovka-kart/" target="_blank" rel="noopener noreferrer">ЦБ: порядок проверки и повтора переводов</a></li></ul>`);else if(a==='privacy')modal('Ваши материалы',`<p>В этой демонстрации выбранные файлы и текст остаются в браузере. Они не отправляются в ВТБ или ИИ-сервис и удаляются из текущего состояния при перезапуске сценария.</p><p>Для примеров показаны заранее подготовленные результаты. Собственный файл или текст можно добавить, но результат анализа для него не формируется.</p><p>Не добавляйте пароли, коды из СМС, реквизиты карты и лишние персональные данные.</p>`);else if(a==='security')modal('Защита в ВТБ Онлайн',`<p>В этом прототипе доступен сценарий проверки переписки перед переводом.</p>${btn('Перейти к проверке','go','secondary','data-screen="upload"')}`);else if(a==='notifications')modal('Уведомления',`<p>Новых уведомлений нет. Чтобы увидеть работу помощника, начните подготовленный перевод.</p>`);else {const labels={topup:'Пополнение счёта',grow:'Расти с ВТБ',qr:'Оплата по QR-коду',mobile:'Мобильная связь',templates:'Шаблоны и автоплатежи'};modal(labels[a]||'Демонстрационный экран',`<p>Этот раздел показан для контекста ВТБ Онлайн. Основной интерактивный сценарий — перевод, проверка переписки и выбор следующего действия.</p>${btn('Начать перевод','go','secondary','data-screen="transfer"')}`)}if(['go','start-demo','demo-overview'].includes(a)&&$('#modal-root').innerHTML)closeModal()});
document.addEventListener('keydown',e=>{if(!$('#modal-root').innerHTML)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const nodes=$('#modal-root').querySelectorAll('button,a[href]');const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});

function externalMaterial(){return `${header('Материал добавлен','upload')}<div class="screen-content white"><div class="result-emblem blue">${icon('image')}</div><h1>Материал добавлен.<br>Разбор не выполнялся.</h1><p class="body-copy">Вы добавили свой материал. В этом прототипе ИИ-модель не подключена, поэтому мы не оцениваем содержание и не делаем вывод о безопасности.</p><div class="callout neutral">${icon('lock')}<span>Файл или текст остаётся только в вашем браузере.</span></div><div class="card" style="margin-top:20px"><h3>Хотите увидеть результат?</h3><p class="body-copy" style="margin:0">Откройте подготовленный пример: в нём показаны фразы из переписки, их объяснение и следующие действия.</p></div></div><footer class="screen-footer">${btn('Показать разбор готового примера','sample-result')}${btn('Вернуться к материалам','go','secondary','data-screen="upload"')}</footer>`}
function startDemo(scenario='job'){reset(scenarios[scenario]?scenario:'job');document.body.classList.add('demo-active');state.screen='transfer';render();window.scrollTo({top:0,behavior:'instant'});$('#demo-guide h2')?.focus({preventScroll:true})}
function showOverview(){clearTimeout(state.analysisTimer);state.analysisToken=null;if(state.screen==='analysis')state.screen='upload';document.body.classList.remove('demo-active');window.scrollTo({top:0,behavior:'instant'});$('#welcome h1')?.focus({preventScroll:true})}
const guideCopy={
 home:[1,'Банковское приложение','Проверка встроена в привычный путь перевода.','Нажмите «В другой банк», чтобы начать.'],
 transfer:[1,'Клиент готовит перевод',null,'Нажмите «Продолжить». Сумма и получатель уже заполнены.'],
 confirm:[1,'Клиент проверяет реквизиты',null,'Нажмите «Перевести». Реального списания нет.'],
 blocked:[2,'Антифрод подаёт сигнал','ML-модель заметила необычную операцию. Появляется предложение помощи, которое можно пропустить.','Нажмите «Разобраться с помощником» или «Пропустить и продолжить».'],
 upload:[3,'Клиент рассказывает о ситуации','Можно говорить, писать или добавить фото. Помощник учитывает причину перевода.','Выберите удобный способ и добавьте готовый пример. Свои материалы не нужны.'],
 analysis:[3,'ИИ обрабатывает запрос','Помощник учитывает контекст и решает, нужна ли проверка сотрудника.','Показываем заранее подготовленный разбор.'],
 result:[4,'Помощник объясняет свой вывод','Оценка ИИ предварительная. При риске или нехватке данных он сам подключает сотрудника.','Откройте чат с сотрудником, чтобы увидеть, как он проверяет вывод.'],
 repeat:[4,'Клиент возвращается к оплате','Сумма и получатель сохранены. Помощник не отменяет обязательные проверки банка.','Подтвердите демонстрационный перевод или вернитесь назад.'],
 done:[5,'Клиент видит итог операции','Сумма, получатель и статус денег остаются понятными.','Можно посмотреть другой пример.'],
 support:[5,'Сотрудник проверяет обстоятельства','Он получает контекст и уточняет факты. Если ИИ ошибся или не учёл детали, сотрудник исправляет оценку.','Выберите готовый ответ клиента и посмотрите вывод сотрудника.'],
 history:[5,'Клиент возвращается к операции','История показывает, выполнен ли перевод, отменён или сохранён на потом.','Выберите операцию, чтобы вернуться к ней.'],
 payments:[1,'Помощь доступна из платежей','Клиент может обратиться самостоятельно. Автоматическое предупреждение появляется только по сигналу ML.','Начните перевод или откройте помощника.'],
 products:[1,'Знакомый банковский интерфейс','Счета и быстрые действия показывают, где появляется сервис.','Нажмите «Перевести деньги».']
};
function renderGuide(){
 const guide=$('#demo-guide');if(!guide)return;let [n,title,copy,next]=guideCopy[state.screen]||guideCopy.transfer;
 const normal=state.scenario==='normal',total=normal?2:5;
 if(normal){n=state.screen==='done'?2:1;title=state.screen==='done'?'Перевод прошёл без плашки':'Обычный перевод';copy=current().context;next=state.screen==='done'?'Антифрод не подал сигнал. Дополнительных действий не потребовалось.':'Продолжите и подтвердите перевод. Предупреждение не появится.'}
 if(state.screen==='result'&&state.source==='external'){title='Свой материал добавлен';copy='ИИ-анализ собственных файлов и текста не подключён. Для знакомства с решением откройте готовый пример.';next='Нажмите «Показать разбор готового примера».'}
 if(state.screen==='upload'&&state.source==='sample')next='Контекст добавлен. Нажмите «Показать ответ помощника».';
 if(state.screen==='result'&&state.source==='sample'&&!state.handoff)next='Можно продолжить перевод или попросить сотрудника проверить ситуацию.';
 if(state.screen==='support'&&state.staffAnswer)next='Сотрудник уточнил обстоятельства. Выберите следующее действие в экране телефона.';
 if(state.screen==='support'&&state.source==='external')next='Произвольный материал не анализируется. Готовый пример показывает полный путь проверки.';
 guide.innerHTML=`<div class="guide-top"><button data-action="demo-overview">← О решении</button><span>Шаг ${n} из ${total}</span></div><div class="guide-progress" aria-hidden="true">${Array.from({length:total},(_,i)=>`<i class="${i<n-1?'complete':i===n-1?'current':''}"></i>`).join('')}</div><h2 class="guide-title" tabindex="-1">${title}</h2><p class="guide-copy">${copy||esc(current().context)}</p><div class="guide-next">${next}</div>`;
 let completion=$('#demo-completion');if(!completion){completion=document.createElement('section');completion.id='demo-completion';completion.className='demo-completion';$('.phone-stage').append(completion)}
 const finished=state.screen==='done'||(state.screen==='support'&&!!state.staffAnswer);completion.hidden=!finished;
 if(finished){
 const takeaway=state.screen==='support'?(state.staffAnswer==='verified'?'Сотрудник уточнил цель и обстоятельства. Подозрение не подтвердилось; клиент может вернуться к оплате.':state.scenario==='purchase'?(state.reviewed?'После уточнения сотрудник изменил рекомендацию ИИ: появилась просьба о предоплате вместо оплаты после осмотра.':'Сотрудник уточнил обстоятельства: вместо оплаты после осмотра потребовали предоплату. Он рекомендовал не переводить деньги.'):'Сотрудник проверил обстоятельства и объяснил, почему деньги лучше не переводить.'):
 state.outcome==='sent'?(normal?'Антифрод не подал сигнал, поэтому плашка не появлялась. Клиент завершил обычный перевод.':state.skipped?'Клиент пропустил добровольную помощь и подтвердил перевод. Обязательные банковские проверки сохраняются.':'После проверки ситуации клиент подтвердил перевод. Оценка ИИ или сотрудника не гарантирует безопасность сделки.'):
 state.outcome==='saved'?'Клиент отложил оплату. Деньги не отправлены.':'Клиент отказался от перевода. Деньги остались на счёте.';
 completion.innerHTML=`<span class="eyebrow">ИТОГ ПРИМЕРА</span><h2>${normal?'Без сигнала нет лишнего шага':state.screen==='support'?(state.reviewed?'Вывод ИИ проверил человек':'Ситуацию проверил сотрудник'):'Клиент выбрал действие'}</h2><p>${takeaway}</p><div class="completion-actions">${btn('Посмотреть другой пример','demo-overview')}${btn('Пройти ещё раз','start-demo','secondary',`data-scenario="${state.scenario}"`)}</div>`;
 }
}
function showDemoSummary(){modal('Что показывает решение',`<p>ML замечает подозрение → появляется плашка с пропуском → клиент рассказывает ситуацию → ИИ объясняет вывод и при необходимости подключает сотрудника → сотрудник проверяет обстоятельства.</p><p>Так предупреждение превращается в понятную помощь в конкретной ситуации.</p>${btn('Посмотреть другие примеры','demo-overview','secondary')}`)}

render();
